/**
 * GENERATED by scripts/build-hand-assets.mjs — do not edit by hand.
 *
 * Whiteboard hand photo assets. `natW`/`natH` are the PNG's real pixels; `ax`/`ay`
 * is where the *working point* (marker nib, pencil point, chalk end, centre of the eraser
 * pad, fingertips of the flat palm) sits inside those pixels; `designH`/`designW` is the
 * size to draw in slide design px (1280×720 space) — ~2× oversampling for retina and for
 * video export. The runtime draws the image at (pen − anchor).
 */
export interface HandAsset {
  src: string
  natW: number
  natH: number
  /** working point inside the PNG (natural px) */
  ax: number
  ay: number
  /** draw at this height (design px) — pens, pencils, chalk */
  designH?: number
  /** draw at this width (design px) — eraser, flat palm */
  designW?: number
}

export const HAND_ASSETS: Record<string, HandAsset> = {
  'marker-dark': { src: '/hands/marker-dark.png', natW: 954, natH: 760, ax: 1, ay: 2, designH: 340 },
  'marker-pale': { src: '/hands/marker-pale.png', natW: 819, natH: 760, ax: 1, ay: 20, designH: 340 },
  'marker-sleeve': { src: '/hands/marker-sleeve.png', natW: 876, natH: 760, ax: 3, ay: 26, designH: 340 },
  'pencil-sleeve': { src: '/hands/pencil-sleeve.png', natW: 975, natH: 760, ax: 0, ay: 0, designH: 340 },
  'chalk-sleeve': { src: '/hands/chalk-sleeve.png', natW: 954, natH: 760, ax: 9, ay: 3, designH: 330 },
  'eraser-sleeve': { src: '/hands/eraser-sleeve.png', natW: 760, natH: 493, ax: 405, ay: 492, designW: 430 },
  'marker-blue': { src: '/hands/marker-blue.png', natW: 819, natH: 760, ax: 1, ay: 20, designH: 340 },
  'pencil': { src: '/hands/pencil.png', natW: 926, natH: 760, ax: 0, ay: 0, designH: 340 },
  'chalk': { src: '/hands/chalk.png', natW: 957, natH: 760, ax: 10, ay: 4, designH: 330 },
  'eraser': { src: '/hands/eraser.png', natW: 760, natH: 629, ax: 353, ay: 628, designW: 430 },
  'palm': { src: '/hands/palm.png', natW: 760, natH: 295, ax: 37, ay: 74, designW: 540 },
}

/** Copy from the surveyed engines: one main hand, one off hand (docs/WHITEBOARD_HAND.md §2). */
export type HandAssetKey =
  | 'marker-dark'
  | 'marker-blue'
  | 'marker-pale'
  | 'marker-sleeve'
  | 'pencil'
  | 'pencil-sleeve'
  | 'chalk'
  | 'chalk-sleeve'
  | 'eraser'
  | 'eraser-sleeve'
  | 'palm'

export function handAsset(key: HandAssetKey): HandAsset {
  return HAND_ASSETS[key] ?? HAND_ASSETS['marker-dark']
}

/** Hand variants that only change who is holding the tool (skin tone / sleeve). */
export type HandTone = 'default' | 'pale' | 'sleeve'
const TONE_KEYS: Record<HandTone, Partial<Record<HandAssetKey, HandAssetKey>>> = {
  default: {},
  // only the tools we have photographed in another tone; anything else falls back to its plate
  pale: { 'marker-dark': 'marker-pale' },
  sleeve: { 'marker-dark': 'marker-sleeve', pencil: 'pencil-sleeve', chalk: 'chalk-sleeve', eraser: 'eraser-sleeve' },
}

export function handKeyFor(key: HandAssetKey, tone: HandTone = 'default'): HandAssetKey {
  return TONE_KEYS[tone]?.[key] ?? key
}

export function handAssetFor(key: HandAssetKey, tone: HandTone = 'default'): HandAsset {
  return handAsset(handKeyFor(key, tone))
}

/** Design-space width of an asset once drawn. */
export function handDrawWidth(a: HandAsset): number {
  return a.designH ? (a.designH * a.natW) / a.natH : (a.designW as number)
}

/** Design-space height of an asset once drawn. */
export function handDrawHeight(a: HandAsset): number {
  return a.designW ? (a.designW * a.natH) / a.natW : (a.designH as number)
}
